BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷103·隐帝本纪·帝死与京师劫掠", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/jiuwudaishi-103-han-emperor-death/source.txt", "note": "《旧五代史》卷103·隐帝本纪·帝死与京师劫掠，段落 jiu-wudaishi-205deb4a7860-p002497；已核上下文及传主，纸本及异文待核。", "id": "cdc30827-1f22-5c39-afe9-0cbc0ce327c8"}, {"title": "旧五代史·卷103·隐帝本纪·刘子陂交战", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/jiuwudaishi-103-liuzi-battle/source.txt", "note": "《旧五代史》卷103·隐帝本纪·刘子陂交战，段落 jiu-wudaishi-205deb4a7860-p002496；已核上下文及传主，纸本及异文待核。", "id": "0dbf0ff5-c440-52dc-a0d7-dc5b99317155"}, {"title": "旧五代史·卷108·张允传·仕宦与墜屋", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/jiuwudaishi-108-zhang-yun-death/source.txt", "note": "《旧五代史》卷108·张允传·仕宦与墜屋，段落 jiu-wudaishi-205deb4a7860-p002607；已核上下文及传主，纸本及异文待核。", "id": "6df16850-2e6d-5849-bda0-f88cd269e02e"}, {"title": "宋史·卷261·刘重进传·汉初邓州", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/songshi-261-liu-chongjin-dengzhou/source.txt", "note": "《宋史》卷261·刘重进传·汉初邓州，段落 songshi-9c6e46fee832-p058060；已核上下文及传主，纸本及异文待核。", "id": "529768d0-e6b8-5788-abc0-d386134e4826"}, {"title": "宋史·卷261·刘重进传·乾祐末拒郭威", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/songshi-261-liu-chongjin-han-general/source.txt", "note": "《宋史》卷261·刘重进传·乾祐末拒郭威，段落 songshi-9c6e46fee832-p058061；已核上下文及传主，纸本及异文待核。", "id": "20b70483-41a1-50b1-8057-67a42bf65de4"}, {"title": "宋史·卷261·刘重进传·契丹通事", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/songshi-261-liu-chongjin-interpreter/source.txt", "note": "《宋史》卷261·刘重进传·契丹通事，段落 songshi-9c6e46fee832-p058059；已核上下文及传主，纸本及异文待核。", "id": "2c7b10e0-5ea0-5a29-a558-33a5ea37c65f"}, {"title": "资治通鉴·卷289·乾祐三年·刘子陂交战与帝死", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/tongjian-289-950-battle-deaths/source.txt", "note": "《资治通鉴》卷289·乾祐三年·刘子陂交战与帝死，段落 zizhi-tongjian-a63549944a71-p003434；已核上下文及传主，纸本及异文待核。", "id": "a9c65e7f-cff5-5395-91ec-98233ac7b126"}, {"title": "资治通鉴·卷289·乾祐三年·京师劫掠与禁止", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/tongjian-289-950-capital-disorder/source.txt", "note": "《资治通鉴》卷289·乾祐三年·京师劫掠与禁止，段落 zizhi-tongjian-a63549944a71-p003435；已核上下文及传主，纸本及异文待核。", "id": "1b8ccf36-7fc8-5273-974f-40e1c53135eb"}, {"title": "新五代史·卷45·袁象先传·二子", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/xinwudaishi-045-yuan-sons/source.txt", "note": "《新五代史》卷45·袁象先传·二子，段落 xin-wudaishi-b08f244b9241-p001673；已核上下文及传主，纸本及异文待核。", "id": "e14bc8bf-f72a-5f77-bd10-1dae6a3d9731"}, {"title": "资治通鉴·卷289·乾祐三年·南下与禁军赏赐", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2acb872f407f87ecc1c683ebe4afe35ab5af384e/content/books/zizhi-tongjian/vol-289/year-0950/part-08/sources/library/tongjian-289-950-guo-march/source.txt", "note": "《资治通鉴》卷289·乾祐三年·南下与禁军赏赐，段落 zizhi-tongjian-a63549944a71-p003433；已核上下文及传主，纸本及异文待核。", "id": "06419fad-ee77-5078-bbd8-5e576df0ff8e"}, {"title": "新五代史·卷10·汉本纪·乾祐三年十一月", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/16c0f5a86200a69c1b027a44e1cd6ceca86246f5/content/books/zizhi-tongjian/vol-289/year-0950/part-07/sources/library/xinwudaishi-010-han-court-killings/source.txt", "note": "《新五代史》卷10·汉本纪·乾祐三年十一月，段落 xin-wudaishi-b08f244b9241-p000353；已核上下文及传主，纸本及异文待核。", "id": "6d0ba205-beb0-5b8b-a95a-2d1e8dbe90d2"}, {"title": "新五代史·卷11·周本纪·郭威南下", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2acb872f407f87ecc1c683ebe4afe35ab5af384e/content/books/zizhi-tongjian/vol-289/year-0950/part-08/sources/library/xinwudaishi-011-guo-march/source.txt", "note": "《新五代史》卷11·周本纪·郭威南下，段落 xin-wudaishi-b08f244b9241-p000366；已核上下文及传主，纸本及异文待核。", "id": "28c8d935-0552-5d17-ac23-4f322402147c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "聂文进", "aliases": ["聶文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州人，后汉枢密承旨，受到刘承祐宠信。950年参与诛杀大臣的谋划，在杨邠等被杀后召朝臣宣布其谋反。生卒年本批未录。", "biography": null, "status": "draft", "id": "947b3f67-2a3c-5318-b225-a83d6b5a9767"}, {"name": "袁嶬", "aliases": ["袁义", "袁義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "袁象先的儿子，950年任左神武统军，受命与刘重进等率禁军在赤冈会师，战败时秘密拜见郭威。通鉴电子本把名写成山义拆字，《新五代史》袁象先传写嶬，《宋史》同次出师写袁义。原字保留，生卒年未载。", "biography": null, "status": "draft", "id": "bba3380d-bf2d-534e-a4c5-c19e9c9d60ca"}, {"name": "刘重进（契丹通事）", "aliases": ["刘重进", "劉重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十一月条下记与萧翰率百骑及其他士卒绕到晋军后方，断粮道及归路，进至栾城。与后汉、后周任节度使的同名刘重进是否同人尚未确认，暂分别识别；生卒年未载。", "biography": null, "status": "draft", "id": "cf2a1610-06dc-5169-8f6e-97abf121abca"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "袁象先", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化二年条所见人物：袁象先。", "biography": null, "status": "draft", "id": "edc0915d-f53a-52bd-9547-8b40fd07fb46"}, {"name": "郭崇威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州马军都指挥使，金城人。937年条中记载他不愿臣服契丹，独自南归。", "biography": null, "status": "draft", "id": "2f1d1823-9873-5df8-83ed-7330578213e6"}, {"name": "李筠（原名李荣）", "aliases": ["李榮（控鶴指揮使）", "李荣（控鹤指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州太原人，初名荣，后来因避周世宗讳改名筠。947年任控鹤指挥使，与何福进筹划恒州起兵，先夺甲库并组织官兵与居民作战。与李昪的父亲李荣、晚唐同名李筠分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "5fa92315-29cb-56c6-9108-8f703de9861a"}, {"name": "吴虔裕", "aliases": ["吳虔裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉河中行营都监。949年四月奉郭威之命，率兵从侧面攻击李守贞出城部队，击败对方并夺取攻城器具。生卒年尚未确定。", "biography": null, "status": "draft", "id": "e576a210-c5b6-5c62-8309-4f25ed7f2693"}, {"name": "张彦超", "aliases": ["張彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张彦超，蔚州刺史、举城归契丹者。", "biography": null, "status": "draft", "id": "abfe6397-741d-5795-88f6-462c9ce4b3b1"}, {"name": "宋延渥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "洛阳人，950年任义成节度使，郭威南下时在滑州迎降。他的妻子是后晋石敬瑭的女儿永宁公主。迎降纪日两部史书有差异，生卒年未载。", "biography": null, "status": "draft", "id": "24f24435-a8b6-5d3e-9f40-ad0e7f494c03"}, {"name": "刘铢", "aliases": ["劉銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "陕地人，任河东左都押牙。947年刘知远任命他为河阳节度使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "bcd8da9c-9e21-53c2-a6be-7a6d37b61a32"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "阎晋卿", "aliases": ["閻晉卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "忻州人，后汉客省使。949年正月河中军夜袭后汉营寨时，提醒将士可以凭黄纸甲在火光下辨认敌军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "cd541c62-d1b8-5017-afb5-ae81ba6585ac"}, {"name": "郭允明", "aliases": ["窦十", "竇十"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原、河东人，小名窦十。曾在刘知远身边服役，后来担任翰林茶酒使兼鞍辔库使。949年为刘承祐近臣，《通鉴》和《旧五代史》都记其受宠。生卒年尚未录入。", "biography": null, "status": "draft", "id": "3bedf030-0a2d-5884-8dd9-eec11a8c4ccc"}, {"name": "李业", "aliases": ["李業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉李太后的弟弟，任武德使，刘知远时掌内库，刘承祐即位后受到宠信。950年与刘承祐等策划诛杀杨邠等大臣。出生与死亡年本批未录。", "biography": null, "status": "draft", "id": "0a670b8c-fe4d-5003-96e0-ac1c6b99b1a0"}, {"name": "后匡赞", "aliases": ["后赞", "後贊", "後匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瑕丘人，后汉飞龙使。949年条下与郭允明一起见于刘承祐近臣的记载。《旧五代史》写后赞，官职及朝廷人物背景相合，本批保留这个异名。生卒年尚未录入。", "biography": null, "status": "draft", "id": "ad25a35f-89f7-538f-8c83-ffe2d366f2ff"}, {"name": "何福进", "aliases": ["何福進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：何福进，宿卫军校、力战者。", "biography": null, "status": "draft", "id": "9212470a-66f0-53db-8b65-ab0f833848be"}, {"name": "白再荣", "aliases": ["白再榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋护圣都指挥使。944年二月甲辰朔奉命驻守马家口。原地名与石赟所守麻家口分别保留，不自动混写。生卒年本批未核。", "biography": null, "status": "draft", "id": "91caa219-2e64-565f-b15f-a4402d8c7b3d"}, {"name": "张允", "aliases": ["張允"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋左散骑常侍。938年二月庚辰向石敬瑭提交《驳赦论》，质疑以大赦消除天灾的做法，得到诏书褒奖。", "biography": null, "status": "draft", "id": "832a2405-9822-5a07-a561-b0b86dee97c8"}, {"name": "贾延徽", "aliases": ["賈延徽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉作坊使，受刘承祐宠信。史书记他想侵占邻居魏仁浦的住宅，多次向皇帝进谗；950年京师动乱中被人抓获交给魏仁浦，魏仁浦拒绝趁乱报怨。生卒年未载。", "biography": null, "status": "draft", "id": "f3764603-dbaa-5dc6-a79a-8e93fd01c6e6"}, {"name": "魏仁浦", "aliases": ["魏仁溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字道济，卫州汲人。后晋末任枢密院小吏，随众被迁往契丹后逃归。947年在巩县迎见刘知远，因熟知军队人数与旧制受到郭威信任。生卒年尚未录入。", "biography": null, "status": "draft", "id": "c2e87754-6e6a-56db-b3e1-45835b2bff92"}, {"name": "赵凤（枣强将领）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "枣强人，950年任右千牛卫大将军。京师动乱中在巷口持弓射杀劫掠者，史书记街坊因此得以保全。与后唐宰相赵凤分开建档，生卒年未载。", "biography": null, "status": "draft", "id": "ae7ae161-4e16-5b21-8c31-79dfc6e9bae9"}, {"name": "李洪建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李业的兄长，950年任侍卫马军都指挥使，后暂判侍卫司相关事务。收到杀王殷家属的命令后，只派人看守并继续供给饮食。生卒年未载。", "biography": null, "status": "draft", "id": "20743d65-b3c4-5fd8-a598-3fa66314e4bc"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "郭威军于壬午到封丘，京师人心惊惧", "start_year": 950, "end_year": 950, "time_original": "950年十一月壬午", "dynasty": "五代十国", "description": "郭威军于壬午到封丘，京师人心惊惧。", "phases": [], "location_name": "封丘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "de15c2aa-68d6-52d2-8f58-6cdefc5a89f6"}, {"title": "李太后哭泣，后悔没有采纳李涛建议", "start_year": 950, "end_year": 950, "time_original": "950年十一月壬午条下", "dynasty": "五代十国", "description": "李太后哭泣，后悔没有采纳李涛建议。", "phases": [], "location_name": "后汉宫廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f4ff5ace-6ee9-53b4-8c7c-21001346b513"}, {"title": "慕容彦超夸口擒郭威，询问兵将后又感到畏惧", "start_year": 950, "end_year": 950, "time_original": "950年十一月壬午条下", "dynasty": "五代十国", "description": "慕容彦超夸口擒郭威，询问兵将后又感到畏惧。", "phases": [], "location_name": "后汉宫廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "20775f0f-3904-5420-abf1-0fda90e0bcb4"}, {"title": "刘承祐再派袁嶬、刘重进等率禁军会师赤冈", "start_year": 950, "end_year": 950, "time_original": "950年十一月壬午条下", "dynasty": "五代十国", "description": "刘承祐再派袁嶬、刘重进等率禁军会师赤冈。", "phases": [], "location_name": "赤冈", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9c23ce64-4597-5a6e-81f3-4b0229c2dcbb"}, {"title": "慕容彦超率大军驻七里店", "start_year": 950, "end_year": 950, "time_original": "950年十一月壬午条下", "dynasty": "五代十国", "descrip